from __future__ import annotations

import argparse
from collections import defaultdict
import csv
from datetime import datetime, timezone
import json
import os
from pathlib import Path
import random
import statistics
import sys
import time
import uuid

ROOT = Path(__file__).resolve().parents[1]
BENCHMARK = ROOT / "benchmark"
GOLD = BENCHMARK / "gold_review_working.csv"
CHUNKS = ROOT / "data" / "processed" / "chunks.jsonl"
VEC_MODEL = "BAAI/bge-small-en-v1.5"
COLLECTION = "pharma_chunks_bge_small_v1"

# Only whitelisted, carefully parameterized query templates; no Cypher
# is generated by inserting user/free-form graph_filter_json strings.
CYPHER = {
    "ingredient": """MATCH (d:Drug)-[:HAS_ACTIVE_INGREDIENT]->(ing:ActiveIngredient {id:$ingredient_id})
RETURN DISTINCT d.id AS drug_id ORDER BY drug_id""",
    "contraindication": """MATCH (d:Drug)-[r:HAS_CONTRAINDICATION]->(c:Contraindication {id:$contraindication_id})
WHERE r.verification_status STARTS WITH 'reviewed:'
RETURN DISTINCT d.id AS drug_id ORDER BY drug_id""",
    "interaction": """MATCH (d:Drug)-[r:INTERACTS_WITH]->(t:InteractionTarget {id:$target_id})
WHERE r.interaction_type = $interaction_type
RETURN DISTINCT d.id AS drug_id ORDER BY drug_id""",
    "interaction_monitor_not_prohibited": """MATCH (d:Drug)-[r:INTERACTS_WITH]->(t:InteractionTarget {id:$target_id})
WHERE r.action_type IN ['MONITOR_INR', 'MONITOR_BLEEDING']
  AND r.interaction_type <> 'CONTRAINDICATED_COADMINISTRATION'
RETURN DISTINCT d.id AS drug_id ORDER BY drug_id""",
    "ingredient_and_contraindication": """MATCH (d:Drug)-[:HAS_ACTIVE_INGREDIENT]->(:ActiveIngredient {id:$ingredient_id})
MATCH (d)-[r:HAS_CONTRAINDICATION]->(:Contraindication {id:$contraindication_id})
WHERE r.verification_status STARTS WITH 'reviewed:'
RETURN DISTINCT d.id AS drug_id ORDER BY drug_id""",
    "ingredient_and_interaction": """MATCH (d:Drug)-[:HAS_ACTIVE_INGREDIENT]->(:ActiveIngredient {id:$ingredient_id})
MATCH (d)-[r:INTERACTS_WITH]->(:InteractionTarget {id:$target_id})
WHERE r.verification_status STARTS WITH 'reviewed:'
RETURN DISTINCT d.id AS drug_id ORDER BY drug_id""",
}
PARAMS = {
    "ingredient": {"ingredient_id"},
    "contraindication": {"contraindication_id"},
    "interaction": {"target_id", "interaction_type"},
    "interaction_monitor_not_prohibited": {"target_id"},
    "ingredient_and_contraindication": {"ingredient_id", "contraindication_id"},
    "ingredient_and_interaction": {"ingredient_id", "target_id"},
}


def read_password():
    val = os.environ.get("NEO4J_PASSWORD", "").strip()
    if val:
        return val
    path = ROOT / ".env"
    if path.exists():
        for row in path.read_text(encoding="utf-8-sig").splitlines():
            if row.strip().startswith("NEO4J_PASSWORD="):
                return row.split("=", 1)[1].strip().strip("\"").strip("'")
    raise RuntimeError("NEO4J_PASSWORD missing in .env or environment (do not paste it in chat).")


def read_gold():
    if not GOLD.exists():
        raise RuntimeError(f"Missing {GOLD}. Finish 10/11 review first.")
    with GOLD.open(encoding="utf-8-sig", newline="") as f:
        rows = list(csv.DictReader(f))
    ids = [r["query_id"] for r in rows]
    expected = [f"Q{i:02}" for i in range(1, 31)]
    if ids != expected:
        raise RuntimeError("Benchmark must contain Q01..Q30 in order without duplicates")
    counts = defaultdict(int)
    for row in rows:
        counts[row["category"]] += 1
        if row.get("review_status") != "approved" or not row.get("gold_drug_ids", "").strip():
            raise RuntimeError(f"{row['query_id']} has no approved gold")
        gold = row["gold_drug_ids"].split("|")
        if len(gold) != len(set(gold)) or not all(v.startswith("DRUG:") for v in gold):
            raise RuntimeError(f"Malformed gold IDs: {row['query_id']}")
        row["gold_set"] = set(gold)
        try:
            row["graph_filter"] = json.loads(row["graph_filter_json"])
        except (ValueError, KeyError) as e:
            raise RuntimeError(f"Bad graph filter {row['query_id']}: {e}") from e
        kind = row["graph_filter"].get("kind")
        if row["category"] == "semantic":
            if kind != "semantic_unconstrained":
                raise RuntimeError("Semantic queries must not have graph answer-leaking filters")
        elif kind not in CYPHER or set(row["graph_filter"]) != PARAMS[kind] | {"kind"}:
            raise RuntimeError(f"Unsupported structured filter: {row['query_id']} {kind}")
    if dict(counts) != {"semantic": 8, "structural": 7, "strict": 10, "multi_hop": 5}:
        raise RuntimeError(f"Unexpected category counts: {dict(counts)}")
    return rows


def read_chunks():
    if not CHUNKS.exists():
        raise RuntimeError(f"Missing chunk corpus: {CHUNKS}")
    by_drug = defaultdict(list)
    seen = set()
    with CHUNKS.open(encoding="utf-8-sig") as f:
        for line in f:
            if not line.strip():
                continue
            row = json.loads(line)
            cid, did = row["chunk_id"], row["drug_id"]
            if cid in seen:
                raise RuntimeError(f"Duplicate chunk: {cid}")
            seen.add(cid)
            by_drug[did].append(cid)
    if len(seen) != 1072 or len(by_drug) != 25:
        raise RuntimeError(f"Expected frozen 1072 chunks and 25 drugs, got {len(seen)}, {len(by_drug)}")
    return by_drug, seen


def graph_search(driver, query):
    obj = query["graph_filter"]
    kind = obj["kind"]
    if kind == "semantic_unconstrained":
        return None   # unsupported: NOT counted as 0-precision graph search
    params = {p: obj[p] for p in PARAMS[kind]}
    with driver.session(database="neo4j") as session:
        rows = session.run(CYPHER[kind], **params)
        return [r["drug_id"] for r in rows]


def qdrant_post(http, url, collection, embedding, limit, allowed_chunks):
    payload = {
        "query": embedding, "limit": limit, "with_payload": ["chunk_id", "drug_id"],
        "params": {"hnsw_ef": 64, "exact": False},
    }
    if allowed_chunks is not None:
        if not allowed_chunks:
            return []
        payload["filter"] = {"must": [{"has_id": [
            str(uuid.uuid5(uuid.NAMESPACE_URL, chunk)) for chunk in allowed_chunks
        ]}]}
    response = http.post(f"{url.rstrip('/')}/collections/{collection}/points/query",
                         json=payload, timeout=120)
    if not response.ok:
        raise RuntimeError(f"Qdrant query error {response.status_code}: {response.text[:300]}")
    return response.json().get("result", {}).get("points", [])


def vector_drugs(http, url, collection, embedding, k, expected_chunks, allowed_chunks=None):
    """Adaptive overfetch: return first k DISTINCT drugs, not first k chunks."""
    if expected_chunks == 0:
        return []
    n = min(expected_chunks, max(32, 8*k))
    while True:
        points = qdrant_post(http, url, collection, embedding, n, allowed_chunks)
        ids, seen = [], set()
        for pt in points:
            did = (pt.get("payload") or {}).get("drug_id")
            if not did:
                raise RuntimeError("Qdrant point missing drug_id payload")
            if did not in seen:
                seen.add(did)
                ids.append(did)
                if len(ids) == k:
                    break
        if len(ids) >= k or n >= expected_chunks or len(points) < n:
            return ids
        n = min(expected_chunks, n * 2)


def score(gold, predicted, k):
    selected = predicted[:k]
    tp = len(set(selected) & gold)
    fp = len(selected) - tp
    return {
        "precision_at_k": tp / k,
        "recall_at_k": tp / len(gold),
        "precision_returned": tp / len(selected) if selected else 0.0,
        "false_positives": fp,
        "false_positive_share": fp / len(selected) if selected else 0.0,
        "returned": len(selected), "tp": tp,
    }


def write_csv(path, rows):
    if not rows:
        return
    with path.open("w", encoding="utf-8-sig", newline="") as fp:
        writer = csv.DictWriter(fp, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)


def preflight(rows, by_drug, chunk_set, driver, http, args):
    all_golds = set().union(*(row["gold_set"] for row in rows))
    if not all_golds.issubset(by_drug):
        raise RuntimeError(f"Gold refers to unindexed drugs: {sorted(all_golds - by_drug)}")
    r = http.get(f"{args.qdrant_url.rstrip('/')}/collections/{args.collection}", timeout=12)
    r.raise_for_status()
    info = r.json()["result"]
    vectors_cfg = (info.get("config", {}).get("params", {}).get("vectors") or {})
    if vectors_cfg.get("size") != 384 or str(vectors_cfg.get("distance", "")).lower() != "cosine":
        raise RuntimeError(f"Qdrant vector configuration mismatch: {vectors_cfg}; need 384-D cosine")
    count = int(info.get("points_count") or 0)
    indexed = int(info.get("indexed_vectors_count") or 0)
    if count != len(chunk_set):
        raise RuntimeError(f"Qdrant points {count} != local chunks {len(chunk_set)}")
    if indexed == 0:
        raise RuntimeError("Qdrant indexed_vectors_count = 0; HNSW not verified")
    with driver.session(database="neo4j") as sess:
        g = sess.run("MATCH (d:Drug) RETURN count(d) AS n").single()["n"]
        c = sess.run("MATCH (c:TextChunk) RETURN count(c) AS n").single()["n"]
        i = sess.run("MATCH ()-[r:INTERACTS_WITH]->() RETURN count(r) AS n").single()["n"]
    if (g, c, i) != (25, 1072, 9):
        raise RuntimeError(f"Neo4j mismatch: Drug={g}, TextChunk={c}, INTERACTS_WITH={i}; expected 25,1072,9")
    mismatches = []
    for row in rows:
        candidates = graph_search(driver, row)
        if candidates is not None and set(candidates) != row["gold_set"]:
            mismatches.append({"query_id": row["query_id"], "graph_ids": candidates,
                               "gold_ids": sorted(row["gold_set"])})
    print(f"Approved gold: {len(rows)}/30 | Qdrant: {count} vectors, indexed={indexed} | Neo4j: {g} drugs, {c} chunks, {i} interactions")
    print(f"Structured query vs approved-gold discrepancies: {len(mismatches)}/22")
    for mismatch in mismatches:
        print("  DISCREPANCY:", mismatch["query_id"], "graph", mismatch["graph_ids"], "gold", mismatch["gold_ids"])
    print("Graph-only applicable to 22 structured questions; not applicable to Q01–Q08.")
    print("Hybrid falls back to vector-only on Q01–Q08 (no graph constraint).")
    print("No clinical safety inference from missing relationships. Gold is used only for diagnostics and scoring.")
    return mismatches


def main():
    p = argparse.ArgumentParser(description=__doc__)
    mode = p.add_mutually_exclusive_group(required=True)
    mode.add_argument("--preflight", action="store_true", help="Check source, graph and vector collection, no embeddings")
    mode.add_argument("--run", action="store_true", help="Execute all 30 queries in 3 modes")
    p.add_argument("--repeats", type=int, default=3)
    p.add_argument("--k", type=int, nargs="+", default=[1, 3, 5], help="Metrics at k=1,3,5")
    p.add_argument("--seed", type=int, default=2026)
    p.add_argument("--collection", default=COLLECTION)
    p.add_argument("--qdrant-url", default="http://127.0.0.1:6333")
    p.add_argument("--neo4j-uri", default="bolt://127.0.0.1:7687")
    args = p.parse_args()
    if args.repeats < 1 or args.repeats > 20 or not args.k or min(args.k) < 1 or max(args.k) > 25:
        p.error("1 <= repeats <= 20 and 1 <= k <= 25 required")
    from neo4j import GraphDatabase
    import requests
    rows = read_gold()
    by_drug, chunk_set = read_chunks()
    driver = GraphDatabase.driver(args.neo4j_uri, auth=("neo4j", read_password()), connection_timeout=15)
    with requests.Session() as http:
        try:
            driver.verify_connectivity()
            discrepancies = preflight(rows, by_drug, chunk_set, driver, http, args)
            if args.preflight:
                return 0 if not discrepancies else 2
            if discrepancies:
                raise RuntimeError("Preflight discrepancies need review. Do not benchmark before resolving.")
            try:
                import psutil
            except ImportError:
                raise RuntimeError("Missing psutil. Install: py -m pip install psutil")
            from fastembed import TextEmbedding
            print(f"Loading local embedding model {VEC_MODEL} (can take a minute)...", flush=True)
            model = TextEmbedding(model_name=VEC_MODEL)
            # Warmup is excluded from measured query-encoding times.
            sample = list(model.embed(["warmup pharmacology query"]))[0].tolist()
            if len(sample) != 384:
                raise RuntimeError("Unexpected embedding dimension: expected 384")
            encoded = {}
            for query in rows:
                start = time.perf_counter_ns()
                vec = list(model.embed([query["query_en"]]))[0].tolist()
                encoded[query["query_id"]] = (vec, (time.perf_counter_ns()-start)/1e6)
            proc = psutil.Process(os.getpid())
            rng = random.Random(args.seed)
            kmax = max(args.k)
            log = []
            for rep in range(1, args.repeats + 1):
                shuffled = rows[:]
                rng.shuffle(shuffled)
                for row in shuffled:
                    qid = row["query_id"]
                    filt_kind = row["graph_filter"]["kind"]
                    supported = filt_kind != "semantic_unconstrained"
                    vec, embed_ms = encoded[qid]
                    # Independent backends measured separately. Hybrid *includes*
                    # its graph prefilter in backend_ms. Encoder time separate.
                    modes = ["vector_only", "graph_only", "hybrid"]
                    rng.shuffle(modes)
                    for name in modes:
                        if name == "graph_only" and not supported:
                            continue
                        start_cpu = proc.cpu_times()
                        before_rss = proc.memory_info().rss
                        t0 = time.perf_counter_ns()
                        if name == "vector_only":
                            found = vector_drugs(http, args.qdrant_url, args.collection,
                                                 vec, kmax, len(chunk_set))
                        elif name == "graph_only":
                            found = graph_search(driver, row)[:kmax]
                        elif not supported:
                            # Honest fallback; semantic-only Hybrid cannot pretend
                            # to have performed a graph filter.
                            found = vector_drugs(http, args.qdrant_url, args.collection,
                                                 vec, kmax, len(chunk_set))
                        else:
                            allowed = graph_search(driver, row)
                            allowed_chunks = [cid for did in allowed for cid in by_drug.get(did, [])]
                            found = vector_drugs(http, args.qdrant_url, args.collection,
                                                 vec, kmax, len(allowed_chunks), allowed_chunks)
                            if not set(found).issubset(set(allowed)):
                                raise RuntimeError(f"Hybrid leaked outside filter: {qid}")
                        backend_ms = (time.perf_counter_ns()-t0)/1e6
                        after_cpu = proc.cpu_times()
                        client_cpu_ms = 1000*((after_cpu.user+after_cpu.system) - (start_cpu.user+start_cpu.system))
                        after_rss = proc.memory_info().rss
                        if len(found) != len(set(found)):
                            raise RuntimeError("Retrieval returned duplicate Drug IDs")
                        for k in sorted(set(args.k)):
                            metrics = score(row["gold_set"], found, k)
                            log.append({
                                "query_id": qid, "category": row["category"], "mode": name,
                                "repeat": rep, "k": k, "gold_count": len(row["gold_set"]),
                                "predicted_drug_ids": "|".join(found[:k]),
                                **metrics,
                                "backend_ms": round(backend_ms, 3),
                                "embed_ms": round(embed_ms, 3) if name != "graph_only" else 0.0,
                                "estimated_total_ms": round(backend_ms + (embed_ms if name != "graph_only" else 0), 3),
                                "client_cpu_ms": round(client_cpu_ms, 3),
                                "client_rss_before_mb": round(before_rss/1024/1024, 3),
                                "client_rss_after_mb": round(after_rss/1024/1024, 3),
                                "semantic_vector_fallback": (not supported and name == "hybrid"),
                            })
                print(f"Finished repeat {rep}/{args.repeats} ({len(shuffled)} queries)", flush=True)
            stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
            destination = BENCHMARK / f"run_{stamp}"
            destination.mkdir(parents=True, exist_ok=False)
            write_csv(destination / "retrieval_results.csv", log)
            summary = []
            # Report per category, and strictly *comparable* 22 structured
            # questions. No false 30-question all-mode average is produced.
            for category in ["semantic", "structural", "strict", "multi_hop", "structured_all"]:
                for name in ["vector_only", "graph_only", "hybrid"]:
                    for k in sorted(set(args.k)):
                        entries = [r for r in log if r["mode"] == name and r["k"] == k and
                                   (r["category"] == category if category != "structured_all" else r["category"] != "semantic")]
                        if not entries:
                            continue
                        def avg(key): return round(statistics.mean(float(z[key]) for z in entries), 5)
                        summary.append({
                            "category": category, "mode": name, "k": k,
                            "observations": len(entries),
                            "mean_precision_at_k": avg("precision_at_k"),
                            "mean_recall_at_k": avg("recall_at_k"),
                            "mean_false_positive_share": avg("false_positive_share"),
                            "mean_returned": avg("returned"),
                            "mean_backend_ms": avg("backend_ms"),
                            "median_backend_ms": round(statistics.median(float(z["backend_ms"]) for z in entries), 5),
                            "mean_estimated_total_ms": avg("estimated_total_ms"),
                            "mean_client_cpu_ms": avg("client_cpu_ms"),
                        })
            write_csv(destination / "summary_by_category.csv", summary)
            manifest = {
                "timestamp_utc": stamp,
                "dataset": {"drug_labels": 25, "text_chunks": 1072, "source": "openFDA frozen 2026-10-16"},
                "engine": {"Qdrant_collection": args.collection, "embedding": VEC_MODEL,
                           "Neo4j_uri": args.neo4j_uri, "Qdrant_url": args.qdrant_url,
                           "Qdrant_params": {"hnsw_ef": 64, "exact": False}},
                "benchmark": {"approved_queries": 30, "structured_comparable_queries": 22,
                              "semantic_graph_only": "not_applicable",
                              "semantic_hybrid": "vector_only_fallback", "repeats": args.repeats, "k": sorted(set(args.k)), "seed": args.seed,
                              "retrieval_unit": "distinct Drug ID"},
                "timing": "Query embedding measured once per question after warmup, reported separately. estimated_total_ms = embed_ms + backend_ms. CPU/RSS are Python CLIENT ONLY; Neo4j/Qdrant Docker resource use is NOT measured here.",
                "limitations": [
                    "Gold is manually reviewed against same frozen corpus; not independent external clinical validation.",
                    "Graph filters are supplied as structured benchmark metadata; free-text constraint extraction is NOT evaluated.",
                    "Graph-only cannot answer semantic_unconstrained questions by design; excluded, not scored zero.",
                    "Hybrid uses vector-only fallback for eight semantic questions, not an independent gain.",
                    "A single underlying medical fact may appear in multiple benchmark questions (correlated cases).",
                    "Measured performance in this small 25-drug corpus does not generalize to clinical usage.",
                    "Recall@k is recall against the judged CORPUS relevance set, not real-world drug completeness.",
                    "Client CPU/RSS excludes Docker containers; collect docker stats separately for full infrastructure CPU/RAM."
                ],
            }
            (destination / "run_manifest.json").write_text(json.dumps(manifest, indent=2, ensure_ascii=False), encoding="utf-8")
            print("SAVED:", destination)
            print("  retrieval_results.csv, summary_by_category.csv, run_manifest.json")
            for r in summary:
                if r["category"] == "structured_all" and r["k"] == 3:
                    print(f"  k=3 structured | {r['mode']:11} P@3={r['mean_precision_at_k']:.3f} "
                          f"R@3={r['mean_recall_at_k']:.3f} backend={r['mean_backend_ms']:.1f}ms")
            print("Note: CPU/RSS here refer to Python client ONLY, not Docker services.")
            return 0
        finally:
            driver.close()


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (RuntimeError, ValueError, OSError, KeyError, json.JSONDecodeError) as exc:
        print("ERROR:", exc, file=sys.stderr)
        raise SystemExit(1)
